import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    coords = sorted({t for s, e, _ in jobs for t in (s, e)})
    idx = {t: i for i, t in enumerate(coords)}
    m = len(coords)

    # Graph adjacency list: [to, cap, cost, rev_idx]
    adj: list[list[list[int]]] = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        adj[u].append([v, cap, cost, len(adj[v])])
        adj[v].append([u, 0, -cost, len(adj[u]) - 1])

    for i in range(m - 1):
        add_edge(i, i + 1, k, 0)

    for s, e, pay in jobs:
        add_edge(idx[s], idx[e], 1, -pay)

    INF = 10**18
    # Initial Johnson potentials via DAG topological order (0 .. m-1)
    h = [INF] * m
    h[0] = 0
    for u in range(m):
        if h[u] == INF:
            continue
        for v, cap, cost, _ in adj[u]:
            if cap > 0 and h[u] + cost < h[v]:
                h[v] = h[u] + cost

    total_pay = 0
    for _ in range(k):
        dist = [INF] * m
        parent_u = [-1] * m
        parent_e = [-1] * m
        dist[0] = 0
        pq = [(0, 0)]

        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            for ei, (v, cap, cost, _) in enumerate(adj[u]):
                if cap > 0:
                    nd = d + cost + h[u] - h[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        parent_u[v] = u
                        parent_e[v] = ei
                        heapq.heappush(pq, (nd, v))

        if dist[m - 1] == INF:
            break

        for i in range(m):
            if dist[i] < INF:
                h[i] += dist[i]

        if h[m - 1] >= 0:
            break

        total_pay -= h[m - 1]
        v = m - 1
        while v != 0:
            u = parent_u[v]
            ei = parent_e[v]
            edge = adj[u][ei]
            edge[1] -= 1
            adj[v][edge[3]][1] += 1
            v = u

    return total_pay
